    // apply_audio_metadata fills empty music fields from probed tags (pipe-joined
    // multi-values) and returns the embedded MusicBrainz ids to persist.
    #[test]
    fn apply_audio_metadata_fills_music_fields_and_returns_mb_ids() {
        use ferrofin_db::entities::base_items::BaseItemEntity;
        use ferrofin_model::media_info::MediaInfo;

        let mut info = MediaInfo {
            album: Some("Kind of Blue".into()),
            artists: vec!["Miles Davis".into()],
            album_artists: vec!["Miles Davis".into()],
            genres: vec!["Jazz".into(), "Modal".into()],
            index_number: Some(3),
            parent_index_number: Some(1),
            production_year: Some(1959),
            ..MediaInfo::default()
        };
        info.provider_ids
            .insert("MusicBrainzAlbum".into(), "album-mbid".into());
        info.provider_ids
            .insert("MusicBrainzArtist".into(), "artist-mbid".into());

        // Empty entity (a bare Audio row) → filled.
        let mut e = BaseItemEntity {
            media_type: Some("Audio".into()),
            ..Default::default()
        };
        let ids = super::apply_audio_metadata(&mut e, &info);
        assert_eq!(e.album.as_deref(), Some("Kind of Blue"));
        assert_eq!(e.artists.as_deref(), Some("Miles Davis"));
        assert_eq!(e.album_artists.as_deref(), Some("Miles Davis"));
        assert_eq!(e.genres.as_deref(), Some("Jazz|Modal"));
        assert_eq!(e.index_number, Some(3));
        assert_eq!(e.parent_index_number, Some(1));
        assert_eq!(e.production_year, Some(1959));
        // MB ids returned for persistence.
        let mut keys: Vec<&str> = ids.iter().map(|(k, _)| k.as_str()).collect();
        keys.sort_unstable();
        assert_eq!(keys, vec!["MusicBrainzAlbum", "MusicBrainzArtist"]);

        // A field already set (e.g. an NFO year) is not overwritten.
        let mut pre = BaseItemEntity {
            production_year: Some(2000),
            album: Some("Existing".into()),
            ..Default::default()
        };
        super::apply_audio_metadata(&mut pre, &info);
        assert_eq!(pre.production_year, Some(2000));
        assert_eq!(pre.album.as_deref(), Some("Existing"));

        // The TITLE tag replaces the resolver's file-stem name, and the ALBUM
        // tag fills the album (the reported music bug: every track/album
        // displayed release-folder noise). The planner's album-folder name on
        // this fixture never reaches the tags: `ResolverGuesses::take` empties
        // `album` first, exactly as the scan does, and the path only locates
        // that folder.
        info.media_source.name = Some("Scar Tissue".into());
        let mut tagged = BaseItemEntity {
            name: Some("03. Red Hot Chili Peppers - Scar Tissue".into()),
            album: Some("RHCP - Californication (1999) FLAC".into()),
            path: Some(
                "/music/RHCP - Californication (1999) FLAC/03. Red Hot Chili Peppers - Scar Tissue.flac"
                    .into(),
            ),
            ..Default::default()
        };
        let _guesses = super::ResolverGuesses::take(&mut tagged, None, false);
        super::apply_audio_metadata(&mut tagged, &info);
        assert_eq!(tagged.name.as_deref(), Some("Scar Tissue"));
        assert_eq!(tagged.album.as_deref(), Some("Kind of Blue"));
    }

    /// "Album artists not provided, fall back to performers (artists)"
    /// (`AudioFileProber.cs:353-357`): a track with no album-artist tag
    /// takes its performers as album artists; a tagged album artist wins, and
    /// a row that already has album artists keeps them (fill-only outside
    /// `ReplaceAllMetadata`).
    #[test]
    fn apply_audio_metadata_falls_back_to_the_performers_for_album_artists() {
        use ferrofin_db::entities::base_items::BaseItemEntity;
        use ferrofin_model::media_info::MediaInfo;

        let untagged = MediaInfo {
            artists: vec!["Miles Davis".into(), "John Coltrane".into()],
            ..MediaInfo::default()
        };
        let mut row = BaseItemEntity::default();
        super::apply_audio_metadata(&mut row, &untagged);
        assert_eq!(
            row.album_artists.as_deref(),
            Some("Miles Davis|John Coltrane")
        );
        assert_eq!(row.artists.as_deref(), Some("Miles Davis|John Coltrane"));

        let tagged = MediaInfo {
            album_artists: vec!["Various Artists".into()],
            ..untagged.clone()
        };
        let mut row = BaseItemEntity::default();
        super::apply_audio_metadata(&mut row, &tagged);
        assert_eq!(row.album_artists.as_deref(), Some("Various Artists"));

        let mut row = BaseItemEntity {
            album_artists: Some("Stored".into()),
            ..BaseItemEntity::default()
        };
        super::apply_audio_metadata(&mut row, &untagged);
        assert_eq!(row.album_artists.as_deref(), Some("Stored"));

        let mut row = BaseItemEntity::default();
        super::apply_audio_metadata(&mut row, &MediaInfo::default());
        assert_eq!(row.album_artists, None, "no performers, no album artists");
    }

    // fanart id selection prefers Tmdb over Imdb; dedup keeps the first image of
    // each type so the one-file-per-type downloader emits no duplicate rows.
    #[test]
    fn fanart_id_selection_and_type_dedup() {
        use ferrofin_model::entities::ImageType;

        // Tmdb preferred.
        let ids = vec![
            ("Imdb".to_owned(), "tt0137523".to_owned()),
            ("Tmdb".to_owned(), "550".to_owned()),
        ];
        assert_eq!(super::fanart_movie_id(&ids).as_deref(), Some("550"));
        // Imdb fallback when no Tmdb.
        let ids = vec![("Imdb".to_owned(), "tt1".to_owned())];
        assert_eq!(super::fanart_movie_id(&ids).as_deref(), Some("tt1"));
        // Neither → None.
        assert!(super::fanart_movie_id(&[("Tvdb".to_owned(), "1".to_owned())]).is_none());

        let img = |t, u: &str| super::RemoteImage {
            image_type: t,
            url: u.to_owned(),
        };
        // append_fanart converts fanart's rich images to type+URL and appends
        // them after the primary provider's; dedup then keeps the first per type.
        let mut images = vec![img(ImageType::Primary, "tmdb-poster")];
        super::append_fanart(
            &mut images,
            vec![
                ferrofin_providers::TmdbImage {
                    image_type: ImageType::Primary,
                    url: "fanart-poster".into(),
                    width: Some(1000),
                    height: None,
                    community_rating: None,
                    vote_count: None,
                    language: None,
                },
                ferrofin_providers::TmdbImage {
                    image_type: ImageType::Logo,
                    url: "fanart-logo".into(),
                    width: Some(800),
                    height: None,
                    community_rating: None,
                    vote_count: None,
                    language: None,
                },
            ],
        );
        let deduped = super::dedup_images_by_type(images);
        let urls: Vec<&str> = deduped.iter().map(|i| i.url.as_str()).collect();
        // TMDB poster keeps Primary; fanart contributes the Logo it lacks.
        assert_eq!(urls, vec!["tmdb-poster", "fanart-logo"]);
    }

    // apply_tvdb_series fills only empty fields and sets the end date for ended
    // series; TVDB people carry no numeric provider id.
    #[test]
    fn apply_tvdb_series_fills_empty_fields_and_end_date() {
        use ferrofin_db::entities::base_items::BaseItemEntity;
        use ferrofin_providers::{TvdbPerson, TvdbSeriesDetails};

        let details = TvdbSeriesDetails {
            tvdb_id: 121_361,
            name: Some("Game of Thrones".into()),
            overview: Some("from tvdb".into()),
            official_rating: Some("TV-MA".into()),
            genres: vec!["Drama".into(), "Fantasy".into()],
            studios: vec!["HBO".into()],
            production_year: Some(2011),
            premiere_date: Some("2011-04-17".into()),
            end_date: Some("2019-05-19".into()),
            status: Some("Ended".into()),
            people: vec![TvdbPerson {
                name: "Emilia Clarke".into(),
                person_type: "Actor".into(),
                role: Some("Daenerys".into()),
                image_url: Some("https://artworks.thetvdb.com/e.jpg".into()),
            }],
            ..TvdbSeriesDetails::default()
        };
        let mut e = BaseItemEntity {
            overview: Some("already set".into()),
            ..Default::default()
        };
        super::apply_tvdb_series(&mut e, &details);
        assert_eq!(e.overview.as_deref(), Some("already set")); // kept
        assert_eq!(e.official_rating.as_deref(), Some("TV-MA")); // filled
        assert_eq!(e.genres.as_deref(), Some("Drama|Fantasy"));
        assert_eq!(e.studios.as_deref(), Some("HBO"));
        assert_eq!(e.production_year, Some(2011));
        assert!(e.premiere_date.is_some());
        assert!(e.end_date.is_some());

        let people = super::tvdb_people(&details.people);
        assert_eq!(people.len(), 1);
        assert_eq!(people[0].name, "Emilia Clarke");
        assert_eq!(people[0].person_type.as_deref(), Some("Actor"));
        assert!(people[0].provider_id.is_none());
        assert_eq!(
            people[0].primary_image_url.as_deref(),
            Some("https://artworks.thetvdb.com/e.jpg")
        );
    }

    // apply_tvdb_episode fills a blank name + air date but never overwrites an
    // existing (NFO/filename) title.
    #[test]
    fn apply_tvdb_episode_fills_blank_name_and_air_date() {
        use ferrofin_db::entities::base_items::BaseItemEntity;
        use ferrofin_providers::TvdbEpisodeDetails;

        let ep = TvdbEpisodeDetails {
            name: Some("Winter Is Coming".into()),
            overview: Some("Ned is summoned.".into()),
            aired: Some("2011-04-17".into()),
            production_year: Some(2011),
            image_url: Some("https://artworks.thetvdb.com/s.jpg".into()),
            people: Vec::new(),
            ..Default::default()
        };
        // Blank name → filled.
        let mut blank = BaseItemEntity::default();
        super::apply_tvdb_episode(&mut blank, &ep);
        assert_eq!(blank.name.as_deref(), Some("Winter Is Coming"));
        assert_eq!(blank.overview.as_deref(), Some("Ned is summoned."));
        assert!(blank.premiere_date.is_some());
        assert_eq!(blank.production_year, Some(2011));
        // The resolver's filename placeholder → replaced (the reported bug:
        // every episode displayed its file name because this guard used to be
        // "only if empty", which the placeholder made permanently false).
        let mut placeholder = BaseItemEntity {
            // A real Episode row: the type drives the per-kind sort-name rule.
            type_: crate::item_type_lookup::stored_type_name(
                ferrofin_model::data::BaseItemKind::Episode,
            )
            .unwrap()
            .to_owned(),
            name: Some("GoT.S01E01.1080p.Bluray".into()),
            sort_name: Some("got.s01e01.1080p.bluray".into()),
            path: Some("/tv/GoT/Season 1/GoT.S01E01.1080p.Bluray.mkv".into()),
            parent_index_number: Some(1),
            index_number: Some(1),
            ..Default::default()
        };
        super::apply_tvdb_episode(&mut placeholder, &ep);
        assert_eq!(placeholder.name.as_deref(), Some("Winter Is Coming"));
        // The new title must NOT become an alphabetical sort name: an episode
        // sorts by its position, or the client's play queue scrambles.
        assert_eq!(
            placeholder.sort_name.as_deref(),
            Some("001 - 0001 - Winter Is Coming")
        );
        // A name that differs from the stem (an NFO <title>) → kept.
        let mut named = BaseItemEntity {
            name: Some("The Real Title".into()),
            path: Some("/tv/GoT/Season 1/GoT.S01E01.1080p.Bluray.mkv".into()),
            ..Default::default()
        };
        super::apply_tvdb_episode(&mut named, &ep);
        assert_eq!(named.name.as_deref(), Some("The Real Title"));
    }

    /// A TVDB stand-in's body for an episode lookup: the series' episode
    /// list and the episode record, crediting `characters` (a JSON array).
    fn tvdb_episode_body(characters: &str) -> &'static str {
        Box::leak(
            format!(
                r#"{{"data":{{"id":121361,"name":"GoT","overview":"TVDB's episode text.",
                "aired":"2011-04-18","episodes":[{{"id":5,"seasonNumber":1,"number":1}}],
                "characters":{characters}}}}}"#
            )
            .into_boxed_str(),
        )
    }

    /// [`tmdb_episode_fixture`] with TheTVDB wired too: a stand-in answering
    /// every episode lookup with `tvdb_body`, and the series known to it.
    async fn tmdb_and_tvdb_episode_fixture(
        tmdb: &str,
        tvdb_body: &'static str,
        tmp: &std::path::Path,
    ) -> (
        LibraryScanner,
        super::ArtworkCache,
        ferrofin_db::entities::base_items::BaseItemEntity,
    ) {
        let the_tvdb = spawn_tvdb_server(None, Some(tvdb_body));
        let (scanner, mut cache, episode) = tmdb_episode_fixture(tmdb, tmp).await;
        let scanner = scanner.with_tvdb(Arc::new(
            ferrofin_providers::TvdbClient::new().with_base_url(&the_tvdb),
        ));
        cache.series_tvdb.insert(
            "SERIES".to_owned(),
            ferrofin_providers::TvdbSeriesDetails {
                tvdb_id: 121_361,
                ..Default::default()
            },
        );
        (scanner, cache, episode)
    }

    /// Runs the remote providers of `episode` on a pass that runs them all.
    async fn fold_episode(
        scanner: &LibraryScanner,
        cache: &mut super::ArtworkCache,
        episode: &mut ferrofin_db::entities::base_items::BaseItemEntity,
        options: Option<&ferrofin_model::configuration::LibraryOptions>,
    ) -> super::RemoteMetadata {
        scanner
            .fetch_remote_metadata(
                episode,
                cache,
                super::FetcherPolicy {
                    options,
                    global: None,
                },
                None,
                &[],
                &super::ResolverGuesses::default(),
            )
            .await
    }

    /// The names each answer credits, in the order the providers ran.
    fn credited(
        answers: &[Option<Vec<ferrofin_db::entities::base_items::PeopleEntity>>],
    ) -> Vec<Option<Vec<String>>> {
        answers
            .iter()
            .map(|a| {
                a.as_ref()
                    .map(|p| p.iter().map(|p| p.name.clone()).collect())
            })
            .collect()
    }

    /// An episode's Cast & Crew is the EPISODE's credits — the series'
    /// regular cast is NOT merged in, which is what made every episode page
    /// show the series list verbatim. Every provider the library runs for
    /// episodes answers with its own `People`, in the order it ran
    /// (`ExecuteRemoteProviders`, `MetadataService.cs:968-1023`): TVDB's is
    /// always a list (the plugin `ResetPeople`s, `TvdbEpisodeProvider.cs:
    /// 225`), even an empty one; TMDB's is null when it credits nobody (it
    /// only `AddPerson`s).
    #[tokio::test]
    async fn every_episode_provider_answers_with_its_own_credits() {
        let credits = r#"[{"personName":"Guest Star","peopleType":"Guest Star","name":"Villain"},
            {"personName":"Ep Director","peopleType":"Director"}]"#;
        let tmp = tempfile::tempdir().unwrap();
        let (tmdb, _hits, _all) = spawn_tmdb_server(Some(SEASON_JSON), Some(CREDITS_JSON));
        let moviedb_cast = [
            "Sean Bean",
            "Maisie Williams",
            "Jason Momoa",
            "Tim Van Patten",
        ]
        .map(str::to_owned)
        .to_vec();
        let thetvdb_cast = ["Guest Star", "Ep Director"].map(str::to_owned).to_vec();

        // No saved order: TheMovieDb (`IHasOrder` 1) runs before TheTVDB (50).
        let (scanner, mut cache, mut episode) =
            tmdb_and_tvdb_episode_fixture(&tmdb, tvdb_episode_body(credits), tmp.path()).await;
        let result = fold_episode(&scanner, &mut cache, &mut episode, None).await;
        assert_eq!(
            credited(&result.credits),
            [Some(moviedb_cast.clone()), Some(thetvdb_cast.clone())]
        );

        // Ranked first, TheTVDB's answer comes first.
        let tvdb_first = tvdb_first_options();
        let (scanner, mut cache, mut episode) =
            tmdb_and_tvdb_episode_fixture(&tmdb, tvdb_episode_body(credits), tmp.path()).await;
        let result = fold_episode(&scanner, &mut cache, &mut episode, Some(&tvdb_first)).await;
        assert_eq!(
            credited(&result.credits),
            [Some(thetvdb_cast), Some(moviedb_cast)]
        );

        // TVDB crediting nobody is still an answer: an empty list. TMDB
        // crediting nobody answers with a null one.
        let (nobody, _hits, _all) =
            spawn_tmdb_server(Some(SEASON_JSON), Some(r#"{"cast":[],"crew":[]}"#));
        let (scanner, mut cache, mut episode) =
            tmdb_and_tvdb_episode_fixture(&nobody, tvdb_episode_body("[]"), tmp.path()).await;
        let result = fold_episode(&scanner, &mut cache, &mut episode, None).await;
        assert_eq!(credited(&result.credits), [None, Some(Vec::new())]);
    }

    // ---------------------------------------------------------------------
    // TMDB episode provider
    // ---------------------------------------------------------------------

    /// A minimal TMDB stand-in serving `/tv/{id}/season/{n}`, counting every
    /// request it receives. Returns `(base_url, hit_counter)`.
    ///
    /// The counter is the point: the season response carries the episode text
    /// AND the artwork, so both scan passes must share one request per season.
    /// A regression that re-fetches per episode still produces correct data —
    /// only the count catches it.
    fn spawn_tmdb_server(
        body: Option<&'static str>,
        credits: Option<&'static str>,
    ) -> (
        String,
        Arc<std::sync::atomic::AtomicUsize>,
        Arc<std::sync::atomic::AtomicUsize>,
    ) {
        spawn_tmdb_server_with_series(body, credits, SERIES_DETAILS_JSON)
    }

    /// [`spawn_tmdb_server`] answering a series' `/tv/{id}` with `series`.
    fn spawn_tmdb_server_with_series(
        body: Option<&'static str>,
        credits: Option<&'static str>,
        series: &'static str,
    ) -> (
        String,
        Arc<std::sync::atomic::AtomicUsize>,
        Arc<std::sync::atomic::AtomicUsize>,
    ) {
        use std::io::{Read as _, Write as _};
        let hits = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        // Every request, not just season fetches: a series lookup never asks
        // for a season, so a season-only counter cannot prove TMDB stayed out.
        let all = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let counter = Arc::clone(&hits);
        let requests = Arc::clone(&all);
        std::thread::spawn(move || {
            for stream in listener.incoming() {
                let Ok(mut s) = stream else { break };
                let mut buf = [0u8; 2048];
                let n = s.read(&mut buf).unwrap_or(0);
                let req = String::from_utf8_lossy(&buf[..n]).into_owned();
                // `/credits` first: its path contains `/season/` too. A `None`
                // body is a MISS — a real non-2xx, not an empty 200, so the
                // caller's failure branch is the one under test.
                requests.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                let episode_payload = credits.map(|c| format!("{{\"credits\":{c}}}"));
                let (status, payload) = if req.contains("/episode/") && !req.contains("/credits") {
                    episode_payload
                        .as_deref()
                        .map_or(("500 Internal Server Error", "{}"), |b| ("200 OK", b))
                } else if req.contains("/credits") {
                    credits.map_or(("500 Internal Server Error", "{}"), |b| ("200 OK", b))
                } else if req.contains("/season/") {
                    counter.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                    body.map_or(("404 Not Found", "{}"), |b| ("200 OK", b))
                } else if req.contains("/search/tv") {
                    ("200 OK", SERIES_SEARCH_JSON)
                } else if req.contains("/tv/") {
                    // `/tv/{id}` — a series detail fetch, answered so a test
                    // can tell which provider wrote which field.
                    ("200 OK", series)
                } else {
                    ("404 Not Found", "{}")
                };
                let _ = write!(
                    s,
                    "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{payload}",
                    payload.len()
                );
            }
        });
        (format!("http://{addr}"), hits, all)
    }

    /// The series search that gives the scan a TMDB id to hang seasons off.
    const SERIES_SEARCH_JSON: &str = r#"{"results": [{"id": 1399, "name": "GoT"}]}"#;

    /// `/tv/{id}` — deliberately a DIFFERENT overview from the TVDB fake's, so
    /// a test can tell which provider wrote the row, and a community rating,
    /// which TVDB never supplies.
    const SERIES_DETAILS_JSON: &str =
        r#"{"overview": "From TMDB.", "genres": [], "vote_average": 8.7}"#;

    /// One episode's credits: two billed regulars, a guest star, a director,
    /// and a job Jellyfin does not map to a person type.
    const CREDITS_JSON: &str = r#"{
        "cast": [
            {"id": 1, "name": "Sean Bean", "character": "Ned Stark"},
            {"id": 2, "name": "Maisie Williams", "character": "Arya Stark"}
        ],
        "guest_stars": [
            {"id": 3, "name": "Jason Momoa", "character": "Khal Drogo"}
        ],
        "crew": [
            {"id": 4, "name": "Tim Van Patten", "job": "Director"},
            {"id": 5, "name": "A Gaffer", "job": "Gaffer"}
        ]
    }"#;

    const SEASON_JSON: &str = r#"{
        "name": "Season 1",
        "overview": "The first season.",
        "poster_path": "/poster.jpg",
        "episodes": [
            {"id": 63056, "episode_number": 1, "name": "Winter Is Coming",
             "overview": "Ned is summoned south.", "still_path": "/e1.jpg",
             "air_date": "2011-04-17", "vote_average": 8.3},
            {"id": 63057, "episode_number": 2, "name": "The Kingsroad",
             "overview": "The party rides north.", "still_path": "/e2.jpg",
             "air_date": "2011-04-24", "vote_average": 0.0}
        ]
    }"#;

    /// Builds a scanner wired to a fake TMDB, plus the episode row the scan
    /// would have planned (name = the file stem, no overview).
    async fn tmdb_episode_fixture(
        base_url: &str,
        tmp: &std::path::Path,
    ) -> (
        LibraryScanner,
        super::ArtworkCache,
        ferrofin_db::entities::base_items::BaseItemEntity,
    ) {
        use ferrofin_db::entities::base_items::BaseItemEntity;
        let db = Database::connect_in_memory().await.unwrap();
        db.run_migrations().await.unwrap();
        let persistence = Arc::new(FerrofinItemPersistenceService::new(db.clone()));
        let vf: Arc<dyn VirtualFolderManager> = Arc::new(
            FerrofinVirtualFolderManager::new(tmp.join("default"))
                .with_item_store(persistence.clone()),
        );
        let tmdb = Arc::new(ferrofin_providers::TmdbClient::new().with_base_url(base_url));
        let scanner = LibraryScanner::new(vf, Arc::new(FerrofinFileSystem::new()), persistence)
            .with_metadata(tmdb, tmp.join("metadata"));

        let mut cache = super::ArtworkCache::default();
        cache.series_tmdb.insert("SERIES".to_owned(), 1399);

        let episode = BaseItemEntity {
            type_: "MediaBrowser.Controller.Entities.TV.Episode".into(),
            name: Some("GoT.S01E01.1080p.Bluray".into()),
            path: Some("/tv/GoT/Season 1/GoT.S01E01.1080p.Bluray.mkv".into()),
            series_id: Some("SERIES".into()),
            parent_index_number: Some(1),
            index_number: Some(1),
            ..Default::default()
        };
        (scanner, cache, episode)
    }

    /// A series with no TMDB id gets no TheMovieDb artwork and asks TMDB
    /// nothing: `TmdbSeriesImageProvider.GetImages` returns nothing when
    /// `item.TryGetTmdbId` fails (`TmdbSeriesImageProvider.cs:58-61`) — it
    /// never searches by name.
    #[tokio::test]
    async fn a_series_without_a_tmdb_id_gets_no_tmdb_artwork() {
        let (base, _, all) = spawn_tmdb_server(None, None);
        let tmdb = ferrofin_providers::TmdbClient::new().with_base_url(&base);
        let series = BaseItemEntity {
            id: "SERIES".into(),
            type_: "MediaBrowser.Controller.Entities.TV.Series".into(),
            name: Some("GoT".into()),
            production_year: Some(2011),
            ..Default::default()
        };
        let mut cache = super::ArtworkCache::default();

        let images = LibraryScanner::series_tmdb_images(&tmdb, &series, &mut cache).await;

        assert!(images.is_empty());
        assert_eq!(
            all.load(std::sync::atomic::Ordering::SeqCst),
            0,
            "no search by name"
        );
        assert!(cache.series_tmdb.is_empty(), "no id was resolved");
    }

    /// Local image validation checks an adopted row's `%MetadataPath%`
    /// token on its expanded path: kept while the file exists, removed once
    /// it is gone.
    #[test]
    fn stored_token_images_are_validated_on_their_expanded_path() {
        use ferrofin_model::entities::ImageType;
        use ferrofin_traits::options::ItemImageInfo;
        let tmp = tempfile::tempdir().unwrap();
        let paths = Arc::new(crate::app_paths::FerrofinServerApplicationPaths::new(
            tmp.path(),
            "log",
            "config",
            "cache",
            "web",
        ));
        let meta = tmp.path().join("metadata");
        paths.set_internal_metadata_path(Some(meta.to_str().unwrap()));
        let expander = crate::virtual_paths::VirtualPathExpander::from_paths(paths);
        let dir = meta.join("library").join("ab");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("poster.jpg"), b"x").unwrap();
        let image = |path: &str, image_type| ItemImageInfo {
            path: path.to_owned(),
            image_type,
            date_modified: chrono::Utc::now(),
            width: 0,
            height: 0,
            blur_hash: None,
        };
        let stored = [
            image("%MetadataPath%/library/ab/poster.jpg", ImageType::Primary),
            image(
                "%MetadataPath%/library/ab/backdrop.jpg",
                ImageType::Backdrop,
            ),
        ];
        let mut images = Vec::new();
        super::keep_stored_images(&mut images, Some(&stored), &expander);
        assert_eq!(
            images,
            vec![stored[0].clone()],
            "the existing one is kept as stored"
        );

        // Unwired (identity) expansion can't check a token path: keep it.
        let mut images = Vec::new();
        super::keep_stored_images(
            &mut images,
            Some(&stored),
            &crate::virtual_paths::VirtualPathExpander::default(),
        );
        assert_eq!(images, stored.to_vec(), "unexpanded token paths are kept");
    }

    /// The D2 backfill heuristics as a remote-metadata trigger, by the
    /// fetcher that runs first. With TVDB first (a saved order ranking it
    /// first; with none TheMovieDb leads) the title/overview gates still
    /// apply, but the trailer and RT gates do not — TVDB supplies neither, so
    /// they would never be met. Once the pass runs, every enabled provider
    /// runs (`MetadataService.cs:696-705`).
    #[tokio::test]
    async fn backfill_gates_follow_the_answering_fetcher() {
        use ferrofin_db::entities::base_items::BaseItemEntity;
        let tmp = tempfile::tempdir().unwrap();
        let (tmdb_only, _cache, _ep) = tmdb_episode_fixture("http://127.0.0.1:1", tmp.path()).await;
        let (with_tvdb, _cache, _ep) = tmdb_episode_fixture("http://127.0.0.1:1", tmp.path()).await;
        let with_tvdb = with_tvdb.with_tvdb(Arc::new(
            ferrofin_providers::TvdbClient::new().with_base_url("http://127.0.0.1:1"),
        ));
        let policy = super::FetcherPolicy::default();
        let tvdb_first = tvdb_first_options();
        let tvdb_policy = super::FetcherPolicy {
            options: Some(&tvdb_first),
            global: None,
        };
        let trailers = Some(r#"{"RemoteTrailers":[{"Url":"https://y/t","Name":"T"}]}"#.to_owned());
        let series = |overview: Option<&str>, data: Option<String>| BaseItemEntity {
            type_: "MediaBrowser.Controller.Entities.TV.Series".into(),
            name: Some("GoT".into()),
            path: Some("/tv/GoT".into()),
            overview: overview.map(str::to_owned),
            data,
            ..Default::default()
        };
        let episode = |name: &str, overview: Option<&str>| BaseItemEntity {
            type_: "MediaBrowser.Controller.Entities.TV.Episode".into(),
            name: Some(name.into()),
            path: Some("/tv/GoT/Season 1/GoT S01E01.mkv".into()),
            overview: overview.map(str::to_owned),
            ..Default::default()
        };
        // TMDB arm: overview and trailers.
        assert!(tmdb_only.wants_backfill(&series(None, trailers.clone()), policy));
        assert!(tmdb_only.wants_backfill(&series(Some("x"), None), policy));
        assert!(!tmdb_only.wants_backfill(&series(Some("x"), trailers.clone()), policy));
        assert!(tmdb_only.wants_backfill(&episode("GoT S01E01", Some("x")), policy));
        assert!(!tmdb_only.wants_backfill(&episode("Pilot", Some("x")), policy));
        // With no saved order TheMovieDb answers first, so its gates apply
        // even with TVDB wired.
        assert!(with_tvdb.wants_backfill(&series(Some("x"), None), policy));
        // TVDB arm (TVDB ranked first): overview only for the series; the
        // episode gate as is.
        assert!(with_tvdb.wants_backfill(&series(None, trailers.clone()), tvdb_policy));
        assert!(
            !with_tvdb.wants_backfill(&series(Some("x"), None), tvdb_policy),
            "TVDB never supplies trailers, so their absence is no trigger"
        );
        assert!(with_tvdb.wants_backfill(&episode("GoT S01E01", Some("x")), tvdb_policy));
        assert!(with_tvdb.wants_backfill(&episode("Pilot", None), tvdb_policy));
        assert!(!with_tvdb.wants_backfill(&episode("Pilot", Some("x")), tvdb_policy));
    }

    // The regression this whole change exists for: on a library migrated from
    // Jellyfin, TheMovieDb is the only metadata fetcher saved for `Episode`, so
    // TMDB must title the episode itself. Before the fix TMDB had no Episode
    // branch at all and every episode kept its filename forever.
    #[tokio::test]
    async fn tmdb_episode_title_replaces_the_filename_placeholder() {
        let (base, _hits, _all) = spawn_tmdb_server(Some(SEASON_JSON), Some(CREDITS_JSON));
        let tmp = tempfile::tempdir().unwrap();
        let (scanner, mut cache, mut episode) = tmdb_episode_fixture(&base, tmp.path()).await;
        // The scan takes the resolver's file-stem name off the row before any
        // provider runs (`ResolverGuesses::take`).
        episode.name = None;

        let result = fold_episode(&scanner, &mut cache, &mut episode, None).await;
        assert!(result.answered);
        assert_eq!(episode.name.as_deref(), Some("Winter Is Coming"));
        assert_eq!(episode.overview.as_deref(), Some("Ned is summoned south."));
        // An episode sorts by position, never alphabetically by the new title,
        // or the client's play queue scrambles: the saved key is settled from
        // the final name and numbers.
        ferrofin_providers::metadata_merge::settle_sort_name(&mut episode);
        assert_eq!(
            episode.sort_name.as_deref(),
            Some("001 - 0001 - Winter Is Coming")
        );
        // The same response carries the air date and rating. With TheTVDB
        // unticked for Episode — the shape that caused this bug — nothing else
        // fills them, and the client shows a dateless, unrated episode.
        assert_eq!(
            episode
                .premiere_date
                .map(|d| d.format("%Y-%m-%d").to_string()),
            Some("2011-04-17".to_owned())
        );
        assert_eq!(episode.production_year, Some(2011));
        assert!((episode.community_rating.expect("rating") - 8.3).abs() < 1e-6);
        // Upstream persists the episode's own Tmdb id.
        assert_eq!(
            result.provider_ids,
            vec![("Tmdb".to_owned(), "63056".to_owned())]
        );
    }

    // TMDB reports 0 for "nobody has rated this yet". Storing it as a rating of
    // zero would show an episode rated 0/10 rather than unrated, and — because
    // every fill here is fill-if-empty — permanently, since a later real rating
    // could never replace it.
    #[tokio::test]
    async fn a_zero_tmdb_vote_is_unrated_not_a_rating_of_zero() {
        let (base, _hits, _all) = spawn_tmdb_server(Some(SEASON_JSON), Some(CREDITS_JSON));
        let tmp = tempfile::tempdir().unwrap();
        let (scanner, mut cache, mut episode) = tmdb_episode_fixture(&base, tmp.path()).await;
        episode.name = Some("GoT.S01E02.1080p.Bluray".into());
        episode.path = Some("/tv/GoT/Season 1/GoT.S01E02.1080p.Bluray.mkv".into());
        episode.index_number = Some(2);

        let answer = scanner
            .fetch_tmdb_episode(&episode, &mut cache, &super::ResolverGuesses::default())
            .await
            .expect("applied");
        assert_eq!(answer.item.name.as_deref(), Some("The Kingsroad"));
        assert_eq!(answer.item.community_rating, None);
        // The air date still lands — only the rating was absent.
        assert_eq!(answer.item.production_year, Some(2011));
    }

    // A library can rank TheTVDB first for `Series` while leaving `Episode` to
    // TMDB. The series then resolves through TVDB and never populates
    // `series_tmdb`, so without the fallback to the Tmdb id TVDB carries, every
    // episode beneath it silently gets nothing.
    #[tokio::test]
    async fn an_episode_resolves_through_the_tmdb_id_tvdb_carries() {
        let (base, _hits, _all) = spawn_tmdb_server(Some(SEASON_JSON), Some(CREDITS_JSON));
        let tmp = tempfile::tempdir().unwrap();
        let (scanner, mut cache, episode) = tmdb_episode_fixture(&base, tmp.path()).await;
        // Only TVDB matched the series.
        cache.series_tmdb.clear();
        cache.series_tvdb.insert(
            "SERIES".to_owned(),
            ferrofin_providers::TvdbSeriesDetails {
                tvdb_id: 121_361,
                tmdb_id: Some("1399".to_owned()),
                ..Default::default()
            },
        );

        let answer = scanner
            .fetch_tmdb_episode(&episode, &mut cache, &super::ResolverGuesses::default())
            .await
            .expect("resolves through TVDB's Tmdb id");
        assert_eq!(answer.item.name.as_deref(), Some("Winter Is Coming"));
    }

    // The episode page exists to show who was in THAT episode. Its credits are
    // the regulars billed in it, then its guest stars, then its crew — never
    // the series' regular cast, which is what every episode page listed before
    // ca2f22c and again after 659b62e gated the only branch that fetched them.
    #[tokio::test]
    async fn tmdb_episode_credits_are_the_episodes_own() {
        let (base, _hits, _all) = spawn_tmdb_server(Some(SEASON_JSON), Some(CREDITS_JSON));
        let tmp = tempfile::tempdir().unwrap();
        let (scanner, mut cache, episode) = tmdb_episode_fixture(&base, tmp.path()).await;

        let answer = scanner
            .fetch_tmdb_episode(&episode, &mut cache, &super::ResolverGuesses::default())
            .await
            .expect("applied");

        let Some(people) = answer.people.as_deref() else {
            panic!("a TMDB answer with credits: {:?}", answer.people);
        };
        let names: Vec<&str> = people.iter().map(|p| p.name.as_str()).collect();
        // Billing order, then the guest star, then the crew. The unmapped
        // "Gaffer" job is dropped, as upstream drops it.
        assert_eq!(
            names,
            vec![
                "Sean Bean",
                "Maisie Williams",
                "Jason Momoa",
                "Tim Van Patten"
            ]
        );
        assert_eq!(people[0].person_type.as_deref(), Some("Actor"));
        assert_eq!(people[0].role.as_deref(), Some("Ned Stark"));
        assert_eq!(people[2].person_type.as_deref(), Some("GuestStar"));
        assert_eq!(people[3].person_type.as_deref(), Some("Director"));
    }

    /// The episode's credits come with its one TMDB episode request: a
    /// failed request is no answer for them (the failure counted by the
    /// request), and an episode TMDB credits nobody on is a null `People`,
    /// as `TmdbEpisodeProvider` only `AddPerson`s; neither clears a stored
    /// cast.
    #[tokio::test]
    async fn a_failed_credits_request_is_not_an_answer() {
        let tmp = tempfile::tempdir().unwrap();
        let lookup = super::ResolverGuesses::default();
        for (credits, expected) in [
            (None, None),
            (Some(r#"{"cast":[]}"#), None),
            (Some(CREDITS_JSON), Some(4)),
        ] {
            let (base, _, _) = spawn_tmdb_server(Some(SEASON_JSON), credits);
            let (scanner, mut cache, episode) = tmdb_episode_fixture(&base, tmp.path()).await;
            let answer = scanner
                .fetch_tmdb_episode(&episode, &mut cache, &lookup)
                .await
                .expect("the season lists the episode");
            assert_eq!(answer.people.map(|p| p.len()), expected, "{credits:?}");
        }
    }

    // An NFO <title> outranks the provider: the local reader ran first and
    // put the name into the pass's `temp`, and a provider's answer only fills
    // what `temp` still lacks (`MergeData(result, temp, [], false, false)`).
    // The overview is still filled, because it was empty.
    #[tokio::test]
    async fn tmdb_episode_keeps_an_nfo_title_but_fills_the_overview() {
        let (base, _hits, _all) = spawn_tmdb_server(Some(SEASON_JSON), Some(CREDITS_JSON));
        let tmp = tempfile::tempdir().unwrap();
        let (scanner, mut cache, mut episode) = tmdb_episode_fixture(&base, tmp.path()).await;
        episode.name = Some("A Title From The NFO".into());

        let result = fold_episode(&scanner, &mut cache, &mut episode, None).await;
        assert!(result.answered);
        assert_eq!(episode.name.as_deref(), Some("A Title From The NFO"));
        assert_eq!(episode.overview.as_deref(), Some("Ned is summoned south."));
    }

    // `/tv/{id}/season/{n}` carries the episode text AND the season poster AND
    // every episode still. One request must serve the whole season across both
    // the metadata and the image pass — otherwise a 10k-episode library pays
    // 10k requests for data it already had.
    #[tokio::test]
    async fn season_details_are_fetched_once_per_season() {
        let (base, hits, _all) = spawn_tmdb_server(Some(SEASON_JSON), Some(CREDITS_JSON));
        let tmp = tempfile::tempdir().unwrap();
        let (scanner, mut cache, ep1) = tmdb_episode_fixture(&base, tmp.path()).await;

        let mut ep2 = ep1.clone();
        ep2.name = Some("GoT.S01E02.1080p.Bluray".into());
        ep2.path = Some("/tv/GoT/Season 1/GoT.S01E02.1080p.Bluray.mkv".into());
        ep2.index_number = Some(2);

        let guesses = super::ResolverGuesses::default();
        let first = scanner
            .fetch_tmdb_episode(&ep1, &mut cache, &guesses)
            .await
            .expect("the first episode");
        let second = scanner
            .fetch_tmdb_episode(&ep2, &mut cache, &guesses)
            .await
            .expect("the second episode");
        // The image pass asks for the same season.
        let poster = scanner
            .season_details_cached(&mut cache, "SERIES", 1)
            .await
            .and_then(|d| d.poster.clone());

        assert_eq!(first.item.name.as_deref(), Some("Winter Is Coming"));
        assert_eq!(second.item.name.as_deref(), Some("The Kingsroad"));
        assert!(poster.is_some());
        assert_eq!(hits.load(std::sync::atomic::Ordering::SeqCst), 1);
    }

    /// The scan's save for one item, as the loop runs it: the resolver's
    /// guesses come off the planned row, `pipeline` plays the providers, and
    /// `saved_row` builds what is written.
    fn save_as(
        stored: Option<&BaseItemEntity>,
        planned: &BaseItemEntity,
        pipeline: impl FnOnce(&mut BaseItemEntity, &super::ResolverGuesses),
        locked: bool,
        probe_ran: bool,
    ) -> BaseItemEntity {
        save_with_locks(stored, planned, pipeline, locked, &[], probe_ran)
    }

    /// [`save_as`] for an item whose `LockedFields` are `locked_fields`.
    fn save_with_locks(
        stored: Option<&BaseItemEntity>,
        planned: &BaseItemEntity,
        pipeline: impl FnOnce(&mut BaseItemEntity, &super::ResolverGuesses),
        locked: bool,
        locked_fields: &[super::MetadataField],
        probe_ran: bool,
    ) -> BaseItemEntity {
        let mut scanned = planned.clone();
        let guesses = super::ResolverGuesses::take(&mut scanned, stored, false);
        pipeline(&mut scanned, &guesses);
        super::saved_row(
            stored,
            &guesses,
            &scanned,
            super::SaveFacts {
                locked,
                probe_ran,
                locked_fields,
                merge: super::MergeMode::DEFAULT,
                before_refresh: true,
                replace_all: false,
                remote_answered: false,
                redated: None,
            },
        )
    }

    fn planned_movie() -> BaseItemEntity {
        use chrono::TimeZone as _;
        let at = |y| chrono::Utc.with_ymd_and_hms(y, 1, 1, 0, 0, 0).unwrap();
        BaseItemEntity {
            id: "ID".into(),
            type_: "MediaBrowser.Controller.Entities.Movies.Movie".into(),
            name: Some("Heat".into()),
            sort_name: Some("heat".into()),
            production_year: Some(1995),
            path: Some("/m/Heat (1995)/Heat (1995).mkv".into()),
            parent_id: Some("NEW-PARENT".into()),
            date_created: Some(at(2026)),
            date_modified: Some(at(2025)),
            size: Some(42),
            data: Some(r#"{"VideoType":"VideoFile"}"#.into()),
            ..BaseItemEntity::default()
        }
    }

    fn planned_episode(number: i64) -> BaseItemEntity {
        BaseItemEntity {
            id: "EP".into(),
            type_: "MediaBrowser.Controller.Entities.TV.Episode".into(),
            name: Some(format!("Show S01E{number:02}")),
            path: Some(format!("/tv/Show/Season 01/Show S01E{number:02}.mkv")),
            series_id: Some("SERIES".into()),
            parent_index_number: Some(1),
            index_number: Some(number),
            ..BaseItemEntity::default()
        }
    }

    /// An owned row by shape: an extra, a stacked part (owned, no
    /// `ExtraType`, no `PrimaryVersionId`) and a local alternate version
    /// (owned and naming its primary).
    fn owned_row(shape: &str) -> BaseItemEntity {
        BaseItemEntity {
            id: "PART".into(),
            type_: "MediaBrowser.Controller.Entities.Video".into(),
            name: Some("Heat cd2".into()),
            path: Some("/m/Heat (1995)/Heat cd2.mkv".into()),
            parent_id: Some("PARENT".into()),
            owner_id: Some("PRIMARY".into()),
            extra_type: (shape == "extra").then_some(2),
            primary_version_id: (shape == "alternate").then(|| "PRIMARY".into()),
            data: Some(r#"{"VideoType":"VideoFile"}"#.into()),
            ..BaseItemEntity::default()
        }
    }

    /// A stored stacked part keeps its own `IsInMixedFolder` on a rescan —
    /// upstream sets it from the primary only when it creates the part
    /// (`Video.cs:690`) — while an extra and a local alternate take the
    /// planner's (`UpdateFromResolvedItem`; an alternate is re-synced from
    /// its primary, `Video.cs:605-609`). A new part takes the planner's.
    #[rstest::rstest]
    #[case::part("part", true)]
    #[case::alternate("alternate", false)]
    #[case::extra("extra", false)]
    fn a_stored_parts_mixed_folder_flag_stands(#[case] shape: &str, #[case] kept: bool) {
        let planned = BaseItemEntity {
            is_in_mixed_folder: false,
            ..owned_row(shape)
        };
        let stored = BaseItemEntity {
            is_in_mixed_folder: true,
            ..owned_row(shape)
        };
        let noop = |_: &mut BaseItemEntity, _: &super::ResolverGuesses| {};
        for locked in [false, true] {
            let saved = save_as(Some(&stored), &planned, noop, locked, false);
            assert_eq!(saved.is_in_mixed_folder, kept, "{shape}, locked {locked}");
        }
        let created = save_as(None, &planned, noop, false, false);
        assert!(
            !created.is_in_mixed_folder,
            "a new {shape} is the planner's"
        );
    }

    /// On a rescan, a stored owned row takes the planner's name only when it
    /// is an extra (`FindExtras`) whose `Name` field is not locked; a stacked
    /// part or a local alternate keeps its stored name, locked or not.
    #[rstest::rstest]
    #[case::extra("extra", &[], true)]
    #[case::extra_name_locked("extra", &[ferrofin_model::entities::MetadataField::Name], false)]
    #[case::extra_other_lock("extra", &[ferrofin_model::entities::MetadataField::Overview], true)]
    #[case::part("part", &[], false)]
    #[case::alternate("alternate", &[], false)]
    fn only_an_extra_takes_the_planners_name(
        #[case] shape: &str,
        #[case] locked_fields: &[ferrofin_model::entities::MetadataField],
        #[case] renamed: bool,
    ) {
        let planned = owned_row(shape);
        let stored = BaseItemEntity {
            name: Some("Heat (Part Two)".into()),
            sort_name: Some("heat (part two)".into()),
            ..owned_row(shape)
        };
        let noop = |_: &mut BaseItemEntity, _: &super::ResolverGuesses| {};
        for locked in [false, true] {
            let mut saved =
                save_with_locks(Some(&stored), &planned, noop, locked, locked_fields, false);
            super::settle_extra_name(&mut saved, &planned, locked_fields);
            let (name, sort_name) = if renamed {
                ("Heat cd2", "heat cd0000000002")
            } else {
                ("Heat (Part Two)", "heat (part two)")
            };
            assert_eq!(
                saved.name.as_deref(),
                Some(name),
                "{shape}, locked {locked}"
            );
            assert_eq!(saved.sort_name.as_deref(), Some(sort_name));
        }
    }

    /// `saved_row` field by field: resolver guesses never replace a stored
    /// value but fill a missing one, provider values replace, file facts
    /// always overlay, and a locked row takes only the file facts.
    #[test]
    fn saved_row_layers_file_facts_and_providers_over_the_stored_row() {
        use chrono::TimeZone as _;
        let at = |y| chrono::Utc.with_ymd_and_hms(y, 1, 1, 0, 0, 0).unwrap();
        let planned = planned_movie();
        let stored = BaseItemEntity {
            name: Some("Heat (Director's Cut)".into()),
            sort_name: Some("heat (director's cut)".into()),
            production_year: Some(1996),
            overview: Some("Stored overview".into()),
            tagline: Some("Stored tagline".into()),
            parent_id: Some("OLD-PARENT".into()),
            date_created: Some(at(2020)),
            date_modified: Some(at(2021)),
            date_last_refreshed: Some(at(2022)),
            size: Some(7),
            run_time_ticks: Some(100),
            data: Some(r#"{"RemoteTrailers":[{"Url":"u"}],"VideoType":"Iso"}"#.into()),
            ..planned.clone()
        };
        // A provider replaced the tagline; nothing else ran.
        let provider = |e: &mut BaseItemEntity, _: &super::ResolverGuesses| {
            e.tagline = Some("Provider tagline".into());
        };

        let saved = save_as(Some(&stored), &planned, provider, false, false);
        assert_eq!(
            saved.name.as_deref(),
            Some("Heat (Director's Cut)"),
            "a resolver guess never wins"
        );
        assert_eq!(
            saved.sort_name.as_deref(),
            Some("heat (directors cut)"),
            "derived from the kept name"
        );
        assert_eq!(saved.production_year, Some(1996));
        assert_eq!(saved.overview.as_deref(), Some("Stored overview"));
        assert_eq!(
            saved.tagline.as_deref(),
            Some("Provider tagline"),
            "a provider wins"
        );
        assert_eq!(
            saved.parent_id.as_deref(),
            Some("NEW-PARENT"),
            "structure is the planner's"
        );
        assert_eq!(saved.date_created, Some(at(2020)), "first import stands");
        assert_eq!(saved.date_modified, Some(at(2025)), "the stat's mtime");
        assert_eq!(saved.size, Some(42), "the stat's length");
        assert_eq!(saved.date_last_refreshed, Some(at(2022)));
        assert_eq!(saved.run_time_ticks, Some(100), "no probe ran");
        let data = crate::item_data::parse_data(saved.data.as_deref());
        assert_eq!(data["VideoType"], "VideoFile", "the resolver's VideoType");
        assert!(data.contains_key("RemoteTrailers"), "a stored key survives");

        // A probe that ran measures the runtime.
        let probed = |e: &mut BaseItemEntity, _: &super::ResolverGuesses| {
            e.run_time_ticks = Some(200);
        };
        let saved = save_as(Some(&stored), &planned, probed, false, true);
        assert_eq!(saved.run_time_ticks, Some(200));

        // A locked row runs no merge: the provider's tagline never lands, and
        // its Data is the stored blob; the file facts still do, the
        // resolver's VideoType among them (`UpdateFromResolvedItem`).
        let saved = save_as(Some(&stored), &planned, provider, true, false);
        assert_eq!(saved.tagline.as_deref(), Some("Stored tagline"));
        let data = crate::item_data::parse_data(saved.data.as_deref());
        let mut expected = crate::item_data::parse_data(stored.data.as_deref());
        expected.insert("VideoType".into(), "VideoFile".into());
        assert_eq!(data, expected);
        assert_eq!(saved.size, Some(42));
        assert_eq!(saved.parent_id.as_deref(), Some("NEW-PARENT"));

        // A new item is the pipeline's row with the guesses filling it.
        let saved = save_as(None, &planned, provider, false, false);
        assert_eq!(saved.name.as_deref(), Some("Heat"));
        assert_eq!(saved.sort_name.as_deref(), Some("heat"));
        assert_eq!(saved.production_year, Some(1995));
        assert_eq!(saved.date_created, Some(at(2026)));
    }

    /// [`save_with_locks`] under `options`: the guesses and the merge as the
    /// scan takes them for a pass with those options. `failed`: a provider
    /// failed; `answered`: a remote provider answered with metadata.
    // The pass's facts, one argument each, as `scan_item` hands them over.
    #[allow(clippy::too_many_arguments)]
    fn save_in_mode(
        stored: Option<&BaseItemEntity>,
        planned: &BaseItemEntity,
        pipeline: impl FnOnce(&mut BaseItemEntity, &super::ResolverGuesses),
        locked_fields: &[super::MetadataField],
        probe_ran: bool,
        options: &super::MetadataRefreshOptions,
        failed: bool,
        answered: bool,
    ) -> BaseItemEntity {
        let mut scanned = planned.clone();
        let guesses =
            super::ResolverGuesses::take(&mut scanned, stored, options.replace_all_metadata);
        pipeline(&mut scanned, &guesses);
        let merge = super::MergeMode::of(
            crate::item_type_lookup::kind_from_type_name(&scanned.type_),
            options,
            super::PassAnswers {
                failed,
                remote: answered,
                any: answered || probe_ran,
                local_locked: false,
                probe_ran,
            },
        );
        super::saved_row(
            stored,
            &guesses,
            &scanned,
            super::SaveFacts {
                locked: false,
                probe_ran,
                locked_fields,
                merge,
                before_refresh: true,
                replace_all: options.replace_all_metadata,
                remote_answered: answered,
                redated: None,
            },
        )
    }

    /// The three dashboard choices as the item-refresh route builds them.
    fn dashboard(choice: &str) -> super::MetadataRefreshOptions {
        use super::MetadataRefreshMode::{Default, FullRefresh};
        match choice {
            "scan" => super::MetadataRefreshOptions::for_item_refresh(
                Default, Default, false, false, false,
            ),
            "missing" => super::MetadataRefreshOptions::for_item_refresh(
                FullRefresh,
                FullRefresh,
                false,
                false,
                false,
            ),
            "replace" => super::MetadataRefreshOptions::for_item_refresh(
                FullRefresh,
                FullRefresh,
                true,
                false,
                false,
            ),
            other => panic!("no choice {other}"),
        }
    }

    /// `RefreshWithProviders`' two `MergeData` calls per mode
    /// (`MetadataService.cs:897-915`): Default replaces with the stored row
    /// as the fallback; "Search for missing metadata" only fills; "Replace
    /// all metadata" replaces without the fallback — unless a provider
    /// failed and no remote one answered — and the NFO's `<lockdata>`
    /// replaces whatever the mode. Kinds whose only providers are custom
    /// ones never lose a stored value.
    #[test]
    // One scenario per assertion block; splitting it would only scatter them.
    #[allow(clippy::too_many_lines)]
    fn the_merge_follows_the_refresh_mode() {
        use super::{MergeMode, MetadataRefreshMode, MetadataRefreshOptions, PassAnswers};
        let movie = Some(BaseItemKind::Movie);
        let answered = PassAnswers {
            remote: true,
            any: true,
            ..PassAnswers::default()
        };
        let of = |options: &MetadataRefreshOptions, answers: PassAnswers| {
            MergeMode::of(movie, options, answers)
        };
        let mode = |keep_existing, replace| MergeMode {
            keep_existing,
            replace,
            replace_tags: false,
            merges: true,
        };
        assert_eq!(
            of(&MetadataRefreshOptions::default(), answered),
            MergeMode::DEFAULT
        );
        assert_eq!(of(&dashboard("scan"), answered), MergeMode::DEFAULT);
        assert_eq!(of(&dashboard("missing"), answered), mode(true, false));
        assert_eq!(of(&dashboard("replace"), answered), mode(false, true));
        assert_eq!(
            of(
                &dashboard("replace"),
                PassAnswers {
                    failed: true,
                    ..answered
                }
            ),
            mode(false, true),
            "one failure does not undo an answered replace"
        );
        assert_eq!(
            of(
                &dashboard("replace"),
                PassAnswers {
                    failed: true,
                    any: true,
                    ..PassAnswers::default()
                }
            ),
            mode(true, true),
            "a failure and no remote answer: the stored values are kept"
        );
        assert_eq!(
            of(&dashboard("replace"), PassAnswers::default()),
            MergeMode {
                merges: false,
                ..mode(true, true)
            },
            "nothing answered (no match, fetchers off): upstream merges nothing"
        );
        // A local answer alone (the NFO, the probe) still replaces.
        assert_eq!(
            of(
                &dashboard("replace"),
                PassAnswers {
                    any: true,
                    ..PassAnswers::default()
                }
            ),
            mode(false, true)
        );
        // `ValidationOnly` never replaces, even with `ReplaceAllMetadata`.
        let validate = MetadataRefreshOptions {
            metadata_refresh_mode: MetadataRefreshMode::ValidationOnly,
            replace_all_metadata: true,
            remove_old_metadata: true,
            ..MetadataRefreshOptions::default()
        };
        assert_eq!(of(&validate, answered), mode(false, false));
        // `isLocalLocked` replaces whatever the mode.
        assert_eq!(
            of(
                &dashboard("missing"),
                PassAnswers {
                    local_locked: true,
                    any: true,
                    ..PassAnswers::default()
                }
            ),
            mode(true, true)
        );
        // Custom-provider-only kinds keep the Default flow; a track's tags
        // replace under `ReplaceAllMetadata` when the probe ran.
        let probed = PassAnswers {
            probe_ran: true,
            any: true,
            ..PassAnswers::default()
        };
        for kind in [
            BaseItemKind::Audio,
            BaseItemKind::AudioBook,
            BaseItemKind::Photo,
            BaseItemKind::PhotoAlbum,
            BaseItemKind::Folder,
        ] {
            let merge = MergeMode::of(Some(kind), &dashboard("replace"), probed);
            assert!(merge.keep_existing && merge.replace, "{kind:?}");
            assert!(
                !merge.merges,
                "{kind:?}: custom providers alone merge nothing"
            );
            assert!(
                MergeMode::of(Some(kind), &dashboard("scan"), answered).merges,
                "{kind:?}: a plugin's metadata source answered"
            );
            assert_eq!(
                merge.replace_tags,
                matches!(kind, BaseItemKind::Audio | BaseItemKind::AudioBook),
                "{kind:?}"
            );
        }
        assert!(
            !MergeMode::of(Some(BaseItemKind::Audio), &dashboard("replace"), answered).replace_tags,
            "no probe, no tags to replace with"
        );
        // The ids follow the mode's `shouldReplace` whatever the kind.
        for (choice, replaces) in [("scan", true), ("missing", false), ("replace", true)] {
            assert_eq!(
                MergeMode::replaces_ids(&dashboard(choice), answered),
                replaces,
                "{choice}"
            );
        }
    }

    /// A plugin metadata source answering for a track merges its ids by the
    /// pass's mode, as `AudioMetadataService` merges any answer
    /// (`SetProviderId` with the mode's `replaceData`): "Search for missing
    /// metadata" keeps the track's stored valid id, "Replace all metadata"
    /// replaces it.
    #[rstest::rstest]
    #[case::missing("missing", STORED_MBID)]
    #[case::replace_all("replace", ANSWERED_MBID)]
    #[tokio::test]
    async fn a_plugins_track_id_merges_by_the_pass_mode(
        #[case] choice: &str,
        #[case] expected: &str,
    ) {
        use ferrofin_traits::persistence::ItemPersistenceService as _;
        struct TrackIds;
        #[async_trait::async_trait]
        impl ferrofin_traits::providers::DynamicMetadataProvider for TrackIds {
            fn name(&self) -> &'static str {
                "track-ids"
            }
            async fn lookup(
                &self,
                _item: &ferrofin_traits::providers::DynamicMetadataLookup,
            ) -> Result<
                Option<ferrofin_traits::providers::DynamicMetadataResult>,
                ferrofin_traits::error::ServiceError,
            > {
                Ok(Some(ferrofin_traits::providers::DynamicMetadataResult {
                    provider_ids: vec![("MusicBrainzTrack".to_owned(), ANSWERED_MBID.to_owned())],
                    ..Default::default()
                }))
            }
        }
        let tmp = tempfile::tempdir().unwrap();
        let media = tmp.path().join("music");
        let album = media.join("Artist").join("Album");
        std::fs::create_dir_all(&album).unwrap();
        let track = album.join("01 - Song.mp3");
        std::fs::write(&track, b"").unwrap();
        let db = Database::connect_in_memory().await.unwrap();
        db.run_migrations().await.unwrap();
        let persistence = Arc::new(FerrofinItemPersistenceService::new(db.clone()));
        let vf: Arc<dyn VirtualFolderManager> = Arc::new(
            FerrofinVirtualFolderManager::new(tmp.path().join("views"))
                .with_item_store(persistence.clone()),
        );
        vf.add_virtual_folder(
            "Music",
            Some(CollectionTypeOptions::music),
            &LibraryOptions {
                path_infos: vec![MediaPathInfo {
                    path: media.to_string_lossy().into_owned(),
                }],
                ..LibraryOptions::default()
            },
        )
        .await
        .unwrap();
        let scanner =
            LibraryScanner::new(vf, Arc::new(FerrofinFileSystem::new()), persistence.clone())
                .with_items(crate::test_support::item_repository_over(db))
                .with_dynamic_providers(vec![Arc::new(TrackIds)]);
        scanner.scan_all().await.unwrap();
        let id =
            crate::item_type_lookup::derive_item_id(BaseItemKind::Audio, &track.to_string_lossy())
                .expect("id");
        let track_id = || async {
            persistence
                .provider_ids_for_items(&[id])
                .await
                .expect("ids")
                .remove(&id)
                .unwrap_or_default()
        };
        assert_eq!(
            track_id().await,
            [("MusicBrainzTrack".to_owned(), ANSWERED_MBID.to_owned())],
            "the first refresh records the plugin's id"
        );
        persistence
            .save_provider_id(id, "MusicBrainzTrack", STORED_MBID)
            .await
            .expect("stored id");

        scanner.scan_with(None, &dashboard(choice)).await.unwrap();
        assert_eq!(
            track_id().await,
            [("MusicBrainzTrack".to_owned(), expected.to_owned())]
        );
    }

    /// The track ids of [`a_plugins_track_id_merges_by_the_pass_mode`].
    const STORED_MBID: &str = "5b11f4ce-a62d-471e-81fc-a69a8278c7da";
    const ANSWERED_MBID: &str = "a3cb23fc-acd3-4ce0-8f36-1e5aa6a18432";

    /// One stored movie with an edited overview, an empty rating and a
    /// tagline no provider supplies, refreshed in each mode by a provider
    /// that answers with an overview and a rating.
    #[test]
    fn each_mode_merges_the_provider_answer_its_own_way() {
        let planned = planned_movie();
        let stored = BaseItemEntity {
            name: Some("Heat".into()),
            production_year: Some(1995),
            overview: Some("My overview".into()),
            community_rating: None,
            tagline: Some("My tagline".into()),
            ..planned.clone()
        };
        let provider = |e: &mut BaseItemEntity, _: &super::ResolverGuesses| {
            e.overview = Some("Provider overview".into());
            e.community_rating = Some(8.3);
        };
        let save = |choice: &str, locks: &[super::MetadataField]| {
            save_in_mode(
                Some(&stored),
                &planned,
                provider,
                locks,
                false,
                &dashboard(choice),
                false,
                true,
            )
        };

        // Default: the provider replaces, the stored row fills the rest.
        let saved = save("scan", &[]);
        assert_eq!(saved.overview.as_deref(), Some("Provider overview"));
        assert_eq!(saved.community_rating, Some(8.3));
        assert_eq!(saved.tagline.as_deref(), Some("My tagline"));

        // "Search for missing metadata": the edit stays, the gap fills.
        let saved = save("missing", &[]);
        assert_eq!(saved.overview.as_deref(), Some("My overview"));
        assert_eq!(saved.community_rating, Some(8.3));
        assert_eq!(saved.tagline.as_deref(), Some("My tagline"));

        // "Replace all metadata": replaced, and what no provider re-supplied
        // is cleared — the tagline, and the year (no path guess refills it).
        let saved = save("replace", &[]);
        assert_eq!(saved.overview.as_deref(), Some("Provider overview"));
        assert_eq!(saved.community_rating, Some(8.3));
        assert_eq!(saved.tagline, None);
        assert_eq!(saved.production_year, None);
        assert_eq!(
            saved.name.as_deref(),
            Some("Heat"),
            "the name is never cleared"
        );

        // … except a locked field.
        let saved = save("replace", &[super::MetadataField::Overview]);
        assert_eq!(saved.overview.as_deref(), Some("My overview"));
        assert_eq!(saved.tagline, None);

        // Every remote provider failed without an answer: nothing is erased.
        let saved = save_in_mode(
            Some(&stored),
            &planned,
            |_, _| {},
            &[],
            false,
            &dashboard("replace"),
            true,
            false,
        );
        assert_eq!(saved.overview.as_deref(), Some("My overview"));
        assert_eq!(saved.tagline.as_deref(), Some("My tagline"));
        assert_eq!(saved.production_year, Some(1995));

        // Nothing answered at all (no match, or the fetchers off): upstream
        // merges nothing, so a replace erases nothing either.
        let saved = save_in_mode(
            Some(&stored),
            &planned,
            |_, _| {},
            &[],
            false,
            &dashboard("replace"),
            false,
            false,
        );
        assert_eq!(saved.overview.as_deref(), Some("My overview"));
        assert_eq!(saved.tagline.as_deref(), Some("My tagline"));
        assert_eq!(saved.production_year, Some(1995));
    }

    /// `FillMissingEpisodeNumbersFromPath(episode, replaceAllMetadata)`: a
    /// replace re-reads an episode's numbers from its path; any other mode
    /// keeps the stored (edited) ones.
    #[test]
    fn a_replace_takes_an_episodes_numbers_from_its_path() {
        let planned = planned_episode(3);
        let stored = BaseItemEntity {
            name: Some("Edited".into()),
            index_number: Some(9),
            parent_index_number: Some(2),
            ..planned.clone()
        };
        let saved = save_in_mode(
            Some(&stored),
            &planned,
            |_, _| {},
            &[],
            false,
            &dashboard("missing"),
            false,
            false,
        );
        assert_eq!(
            (saved.parent_index_number, saved.index_number),
            (Some(2), Some(9))
        );
        let saved = save_in_mode(
            Some(&stored),
            &planned,
            |_, guesses| {
                assert_eq!(
                    guesses.index_number,
                    Some(3),
                    "looked up by the path's number"
                );
            },
            &[],
            false,
            &dashboard("replace"),
            false,
            true,
        );
        assert_eq!(
            (saved.parent_index_number, saved.index_number),
            (Some(1), Some(3))
        );
        // An answer that carries no episode number (an NFO without
        // `<episode>`, no remote provider) clears it under
        // `RemoveOldMetadata`, as upstream's merge does; the season number
        // rides on the provider result from the item itself.
        let saved = save_in_mode(
            Some(&stored),
            &planned,
            |_, _| {},
            &[],
            true,
            &dashboard("replace"),
            false,
            false,
        );
        assert_eq!(
            (saved.parent_index_number, saved.index_number),
            (Some(1), None)
        );

        // A season's number comes back too (its provider answers with the
        // number it was looked up by); it stays the stored one.
        let season = BaseItemEntity {
            id: "SEASON".into(),
            type_: "MediaBrowser.Controller.Entities.TV.Season".into(),
            name: Some("Season 1".into()),
            path: Some("/tv/Show/Season 01".into()),
            index_number: Some(1),
            ..BaseItemEntity::default()
        };
        let stored = BaseItemEntity {
            index_number: Some(4),
            overview: Some("Stored".into()),
            ..season.clone()
        };
        let saved = save_in_mode(
            Some(&stored),
            &season,
            |_, _| {},
            &[],
            false,
            &dashboard("replace"),
            false,
            true,
        );
        assert_eq!(saved.index_number, Some(4));
        assert_eq!(saved.overview, None, "the rest is cleared");
    }

    /// `AudioFileProber` under `ReplaceAllMetadata`: the tags replace the
    /// album, the numbers (even with none) and the genres; artists only when
    /// the tag has some, and never under a `Cast` lock. Any other mode only
    /// fills.
    #[test]
    fn a_replace_lets_a_tracks_tags_replace_the_stored_ones() {
        let planned = BaseItemEntity {
            id: "TRACK".into(),
            type_: "MediaBrowser.Controller.Entities.Audio.Audio".into(),
            name: Some("01 - Song".into()),
            path: Some("/music/Artist/Album/01 - Song.mp3".into()),
            index_number: Some(1),
            album: Some("Album".into()),
            ..BaseItemEntity::default()
        };
        let stored = BaseItemEntity {
            name: Some("Song".into()),
            album: Some("Edited Album".into()),
            index_number: Some(7),
            parent_index_number: Some(2),
            genres: Some("Edited".into()),
            artists: Some("Edited Artist".into()),
            album_artists: Some("Edited AA".into()),
            ..planned.clone()
        };
        // Tags: a title, an album and a genre; no numbers, no artists.
        let tags = |e: &mut BaseItemEntity, _: &super::ResolverGuesses| {
            e.name = Some("Tag Title".into());
            e.album = Some("Tag Album".into());
            e.genres = Some("Rock".into());
        };
        let saved = save_in_mode(
            Some(&stored),
            &planned,
            tags,
            &[],
            true,
            &dashboard("scan"),
            false,
            false,
        );
        assert_eq!(
            saved.name.as_deref(),
            Some("Tag Title"),
            "the title replaces"
        );
        assert_eq!(saved.album.as_deref(), Some("Edited Album"));
        assert_eq!(saved.index_number, Some(7));
        assert_eq!(saved.genres.as_deref(), Some("Edited"));

        let saved = save_in_mode(
            Some(&stored),
            &planned,
            tags,
            &[],
            true,
            &dashboard("replace"),
            false,
            false,
        );
        assert_eq!(saved.name.as_deref(), Some("Tag Title"));
        assert_eq!(saved.album.as_deref(), Some("Tag Album"));
        assert_eq!(
            (saved.index_number, saved.parent_index_number),
            (None, None),
            "`audio.IndexNumber = trackTrackNumber`, even without a tag"
        );
        assert_eq!(saved.genres.as_deref(), Some("Rock"));
        assert_eq!(
            saved.artists.as_deref(),
            Some("Edited Artist"),
            "no tag, kept"
        );

        let with_artist = |e: &mut BaseItemEntity, g: &super::ResolverGuesses| {
            tags(e, g);
            e.artists = Some("Tag Artist".into());
        };
        let saved = save_in_mode(
            Some(&stored),
            &planned,
            with_artist,
            &[],
            true,
            &dashboard("replace"),
            false,
            false,
        );
        assert_eq!(saved.artists.as_deref(), Some("Tag Artist"));
        let saved = save_in_mode(
            Some(&stored),
            &planned,
            with_artist,
            &[super::MetadataField::Cast, super::MetadataField::Genres],
            true,
            &dashboard("replace"),
            false,
            false,
        );
        assert_eq!(
            saved.artists.as_deref(),
            Some("Edited Artist"),
            "Cast locked"
        );
        assert_eq!(saved.genres.as_deref(), Some("Edited"), "Genres locked");
    }

    /// `RefreshArtist`'s scope: the artist folders' CHILDREN and the artist
    /// itself take the options; those folders' own artists, and the folders
    /// above them, do not.
    #[test]
    fn an_artist_refresh_covers_the_folders_children_and_the_artist_only() {
        let artist = uuid::Uuid::from_u128(0xA);
        let roots = vec!["/music/Artist B".to_owned()];
        let scope = super::PathScope {
            prune: true,
            roots: &roots,
            roots_refreshed: false,
            also: Some(artist),
            carried: None,
            regrouped: None,
            moved: None,
        };
        let at = |id: u128, path: &str| super::Planned {
            id: uuid::Uuid::from_u128(id),
            entity: BaseItemEntity {
                path: Some(path.to_owned()),
                ..BaseItemEntity::default()
            },
            ancestors: Vec::new(),
        };
        assert!(
            scope.covers(&at(0xA, "/music/Artist A")),
            "the artist itself"
        );
        assert!(scope.covers(&at(1, "/music/Artist B/Duets")));
        assert!(scope.covers(&at(2, "/music/Artist B/Duets/01 - Song.mp3")));
        assert!(
            !scope.covers(&at(3, "/music/Artist B")),
            "the folder's own artist"
        );
        assert!(
            !scope.covers(&at(4, "/music/Artist B/")),
            "however it is spelled"
        );
        assert!(!scope.covers(&at(5, "/music")), "above the folders");
        assert!(
            !scope.covers(&at(6, "/music/Artist A/Album A1")),
            "the artist's own albums"
        );
    }

    /// A scope covering one member of a local group carries what that member
    /// owns into its refresh and regroups the rest — the primary, its parts,
    /// its alternates and theirs — and nothing else: not an extra the
    /// primary owns, not another movie.
    #[test]
    fn a_scope_over_one_version_carries_its_whole_group() {
        use ferrofin_db::store::guid_to_db;
        let id = uuid::Uuid::from_u128;
        let row = |n: u128, path: &str, owner: Option<u128>, shape: &str| super::Planned {
            id: id(n),
            entity: BaseItemEntity {
                id: guid_to_db(id(n)),
                path: Some(format!("/movies/Twins/{path}")),
                owner_id: owner.map(|o| guid_to_db(id(o))),
                primary_version_id: (shape == "alternate").then(|| guid_to_db(id(owner.unwrap()))),
                extra_type: (shape == "extra").then_some(1),
                ..BaseItemEntity::default()
            },
            ancestors: Vec::new(),
        };
        let planned = [
            row(1, "Twins.mkv", None, "primary"),
            row(2, "Twins cd2.mkv", Some(1), "part"),
            row(3, "Twins - 1080p part1.mkv", Some(1), "alternate"),
            row(4, "Twins - 1080p part2.mkv", Some(3), "part"),
            row(5, "Twins-trailer.mkv", Some(1), "extra"),
            row(6, "Other.mkv", None, "primary"),
        ];
        let roots = vec!["/movies/Twins/Twins - 1080p part2.mkv".to_owned()];
        let scope = super::PathScope::of(&roots, true);
        let sorted = |set: std::collections::HashSet<uuid::Uuid>| {
            let mut ids: Vec<_> = set.into_iter().collect();
            ids.sort();
            ids
        };
        // Over the alternate's part: the primary, its part and the alternate
        // are above or beside it.
        let (down, up) = super::covered_versions(&planned, scope);
        assert!(down.is_empty());
        assert_eq!(sorted(up), vec![id(1), id(2), id(3)]);
        // Over the alternate: its part refreshes with it; the primary and its
        // part are only regrouped.
        let roots = vec!["/movies/Twins/Twins - 1080p part1.mkv".to_owned()];
        let (down, up) = super::covered_versions(&planned, super::PathScope::of(&roots, true));
        assert_eq!(sorted(down), vec![id(4)]);
        assert_eq!(sorted(up), vec![id(1), id(2)]);
        // Over the primary: everything it owns that is no extra refreshes.
        let roots = vec!["/movies/Twins/Twins.mkv".to_owned()];
        let (down, up) = super::covered_versions(&planned, super::PathScope::of(&roots, true));
        assert_eq!(sorted(down), vec![id(2), id(3), id(4)]);
        assert!(up.is_empty());
        let roots = vec!["/movies/Twins/Other.mkv".to_owned()];
        let (down, up) = super::covered_versions(&planned, super::PathScope::of(&roots, true));
        assert!(down.is_empty() && up.is_empty());
    }

    /// A path-scoped refresh gives its options to the items at or under its
    /// roots only; the ancestors planned around them take the defaults.
    #[test]
    fn a_path_scoped_refresh_scopes_its_options_to_its_roots() {
        let replace = dashboard("replace");
        let defaults = super::MetadataRefreshOptions::default();
        let roots = vec!["/tv/Show/Season 01".to_owned()];
        let refresh = super::RefreshContext {
            request: super::RefreshRequest {
                options: &replace,
                force_save: true,
            },
            context: super::RefreshRequest {
                options: &defaults,
                force_save: false,
            },
            scope: Some(super::PathScope::of(&roots, true)),
            now: chrono::Utc::now(),
            policies: &std::collections::HashMap::new(),
            outside: super::FetcherPolicy::default(),
            locked: &std::collections::HashSet::new(),
            externals: None,
            superseded: std::collections::HashSet::new(),
            date_added: super::DateAdded::default(),
            cancel: &super::ScanCancel::new(),
            version_groups: &super::VersionGroups::default(),
        };
        let at = |path: &str| super::Planned {
            id: uuid::Uuid::nil(),
            entity: BaseItemEntity {
                path: Some(path.to_owned()),
                ..BaseItemEntity::default()
            },
            ancestors: Vec::new(),
        };
        assert!(
            refresh
                .request_for(&at("/tv/Show/Season 01"), true)
                .force_save
        );
        assert!(
            refresh
                .request_for(&at("/tv/Show/Season 01/Show S01E01.mkv"), true)
                .force_save
        );
        assert!(
            !refresh.request_for(&at("/tv/Show"), true).force_save,
            "the series is context"
        );
        assert!(
            !refresh
                .request_for(&at("/tv/Show/Season 010"), true)
                .force_save
        );
        assert!(
            refresh.request_for(&at("/tv/Show"), false).force_save,
            "a folder above the roots that is not stored yet is created with the scan's options"
        );
        assert!(!refresh.context_only(), "the defaults refresh the context");
    }

    /// Phase 3L: a rescan whose providers run (Default mode's
    /// replace-with-fallback merge) replaces the unlocked fields and leaves
    /// the locked ones as stored (`MergeData(temp, metadata,
    /// item.LockedFields, shouldReplace, true)`).
    #[test]
    fn a_provider_pass_keeps_the_locked_fields_and_replaces_the_rest() {
        let planned = planned_movie();
        let stored = BaseItemEntity {
            name: Some("My Heat".into()),
            overview: Some("My own overview".into()),
            genres: Some("Drama".into()),
            tagline: Some("Stored tagline".into()),
            ..planned.clone()
        };
        let provider = |e: &mut BaseItemEntity, _: &super::ResolverGuesses| {
            e.name = Some("Heat".into());
            e.overview = Some("A group of professional bank robbers…".into());
            e.genres = Some("Action|Crime".into());
            e.tagline = Some("A Los Angeles crime saga".into());
        };
        let locks = [super::MetadataField::Overview, super::MetadataField::Genres];
        let saved = save_with_locks(Some(&stored), &planned, provider, false, &locks, false);
        assert_eq!(saved.overview.as_deref(), Some("My own overview"));
        assert_eq!(saved.genres.as_deref(), Some("Drama"));
        assert_eq!(saved.name.as_deref(), Some("Heat"), "unlocked: replaced");
        assert_eq!(saved.tagline.as_deref(), Some("A Los Angeles crime saga"));

        // No providers ran (an unchanged item, or one whose only change was
        // its file): the edit survives without any lock.
        let saved = save_as(Some(&stored), &planned, |_, _| {}, false, false);
        assert_eq!(saved.overview.as_deref(), Some("My own overview"));
        assert_eq!(saved.name.as_deref(), Some("My Heat"));

        // Unknown links lock everything: a read failure never overwrites.
        let saved = save_with_locks(
            Some(&stored),
            &planned,
            provider,
            false,
            super::ALL_LOCKABLE_FIELDS,
            false,
        );
        assert_eq!(saved.name.as_deref(), Some("My Heat"));
        assert_eq!(saved.overview.as_deref(), Some("My own overview"));
        assert_eq!(
            saved.tagline.as_deref(),
            Some("A Los Angeles crime saga"),
            "Tagline is not a lockable field"
        );
    }

    /// Review regression (a): a provider value that happens to equal the
